266	  const [oauth2Scopes, setOAuth2Scopes] = useState<string>("");
267	  const [selectedTemplate, setSelectedTemplate] = useState<string>(DEFAULT_TEMPLATE);
268	  const [isSubmitting, setIsSubmitting] = useState(false);
269	  const isCreating = identityProvider === undefined;
270	  const oauth2FieldMapping = oauth2Config.fieldMapping ?? createEmptyFieldMapping();
271	
272	  useEffect(() => {
273	    if (!open) {
274	      setSelectedTemplate(DEFAULT_TEMPLATE);
275	      setBasicInfo(createEmptyBasicInfo());
276	      setType(IdentityProvider_Type.OAUTH2);
277	      setOAuth2Config(createEmptyOAuth2Config());
278	      setOAuth2Scopes("");
279	      setIsSubmitting(false);
280	      return;
281	    }
282	
283	    const nextState = isCreating ? buildDialogStateFromTemplate(selectedTemplate) : buildDialogStateFromProvider(identityProvider!);
284	    setBasicInfo(nextState.basicInfo);
285	    setType(nextState.type);
286	    setOAuth2Config(nextState.oauth2Config);
287	    setOAuth2Scopes(nextState.oauth2Scopes);
288	  }, [open, isCreating, identityProvider, selectedTemplate]);
