290	  const handleDialogClose = (nextOpen: boolean) => {
291	    if (isSubmitting && !nextOpen) {
292	      return;
293	    }
294	    onOpenChange(nextOpen);
295	  };
296	
297	  const handleCloseBtnClick = () => {
298	    if (isSubmitting) {
299	      return;
300	    }
301	    handleDialogClose(false);
302	  };
303	
304	  const allowConfirmAction = () => {
305	    if (basicInfo.title.trim() === "") {
306	      return false;
307	    }
308	    if (isCreating && basicInfo.identifier.trim() === "") {
309	      return false;
310	    }
311	    if (type === IdentityProvider_Type.OAUTH2) {
312	      if (
313	        oauth2Config.clientId.trim() === "" ||
314	        oauth2Config.authUrl.trim() === "" ||
315	        oauth2Config.tokenUrl.trim() === "" ||
316	        oauth2Config.userInfoUrl.trim() === "" ||
317	        normalizeScopes(oauth2Scopes).length === 0 ||
318	        oauth2FieldMapping.identifier.trim() === ""
319	      ) {
320	        return false;
321	      }
322	      if (isCreating && oauth2Config.clientSecret.trim() === "") {
323	        return false;
324	      }
325	    }
326	
327	    return !isSubmitting;
328	  };
329	
330	  const handleConfirmBtnClick = async () => {
331	    setIsSubmitting(true);
332	    const normalizedScopes = normalizeScopes(oauth2Scopes);
333	
334	    try {
335	      if (isCreating) {
336	        await identityProviderServiceClient.createIdentityProvider({
337	          identityProviderId: basicInfo.identifier,
338	          identityProvider: create(IdentityProviderSchema, {
339	            title: basicInfo.title.trim(),
340	            identifierFilter: basicInfo.identifierFilter.trim(),
341	            type,
342	            config: create(IdentityProviderConfigSchema, {
343	              config: {
344	                case: "oauth2Config",
345	                value: {
346	                  ...oauth2Config,
347	                  scopes: normalizedScopes,
348	                },
349	              },
350	            }),
351	          }),
352	        });
353	        toast.success(t("setting.sso.sso-created", { name: basicInfo.title }));
354	      } else {
355	        await identityProviderServiceClient.updateIdentityProvider({
356	          identityProvider: create(IdentityProviderSchema, {
357	            name: identityProvider!.name,
358	            title: basicInfo.title.trim(),
359	            identifierFilter: basicInfo.identifierFilter.trim(),
360	            type,
361	            config: create(IdentityProviderConfigSchema, {
362	              config: {
363	                case: "oauth2Config",
364	                value: {
365	                  ...oauth2Config,
366	                  scopes: normalizedScopes,
367	                },
368	              },
369	            }),
370	          }),
371	          updateMask: create(FieldMaskSchema, { paths: ["title", "identifier_filter", "config"] }),
